     3	/// `vp9_alpha_webm`'s encoder (spec §11 CX-17 (3), (4)): two encoders fed the same frames —
     4	/// the picture's (`VP9Encoder` exactly as `vp9_webm`'s 8-bit, with forced keys) and the
     5	/// alpha's (`VP9Encoder.Plane.alpha`, constant quality, full range) — answering a packet only
     6	/// when both have answered that frame, the alpha's bytes in its `alpha`.
     7	///
     8	/// **Paired by pts.** Each encoder's packets wait in a queue of their own; the oldest of each
     9	/// are paired when both queues have one. An alpha packet at another frame than the picture's,
    10	/// or one that disagrees on being a keyframe, fails the export in its own sentence: the WebM
    11	/// writer would otherwise put one frame's alpha under another's picture, or a key's alpha
    12	/// under an inter frame a seek cannot decode. The keys agree by construction (both encoders'
    13	/// `keyInterval`), so either sentence is a defect, never a file.
    14	///
    15	/// Every call is made on the pump's encode queue alone, as on any `ExportVideoEncoder`.
    16	final class VP9AlphaEncoder: ExportVideoEncoder {
    17	    let name = "libvpx"
    18	
    19	    private let picture: any ExportVideoEncoder
    20	    private let alpha: any ExportVideoEncoder
    21	    private var pictures: [ExportEncodedPacket] = []
    22	    private var alphas: [ExportEncodedPacket] = []
    23	    /// Set once a stream has answered its last packet after the end of stream.
    24	    private var pictureDrained = false
    25	    private var alphaDrained = false
    26	
    27	    init(picture: any ExportVideoEncoder, alpha: any ExportVideoEncoder) {
    28	        self.picture = picture
    29	        self.alpha = alpha
    30	    }
    31	
    32	    @available(*, unavailable) required init?(coder: NSCoder) {
    33	        fatalError("VP9AlphaEncoder does not support NSCoder")
    34	    }
    35	
    36	    /// The two libvpx encoders of an 8-bit SDR picture at the export's size and rate, their
    37	    /// keys forced every `VP9Encoder.keyInterval(fps:)` frames; the cap is the picture's alone.
    38	    static func make(width: Int, height: Int, fps: Fps, bitsPerSecond: Int) throws
    39	        -> VP9AlphaEncoder
    40	    {
    41	        let interval = VP9Encoder.keyInterval(fps: fps)
    42	        return VP9AlphaEncoder(
    43	            picture: try VP9Encoder(
    44	                width: width, height: height, fps: fps, bitsPerSecond: bitsPerSecond,
    45	                picture: .sdr, plane: .picture, keyInterval: interval),
    46	            alpha: try VP9Encoder(
    47	                width: width, height: height, fps: fps, bitsPerSecond: bitsPerSecond,
    48	                picture: .sdr, plane: .alpha, keyInterval: interval))
    49	    }
    50	
    51	    func send(_ frame: I010Frame, index: Int64) throws {
    52	        try picture.send(frame, index: index)
    53	        try alpha.send(frame, index: index)
    54	    }
    55	
    56	    func sendEndOfStream() throws {
    57	        try picture.sendEndOfStream()
    58	        try alpha.sendEndOfStream()
    59	    }
    60	
    61	    /// The next frame both streams have answered, the alpha's bytes in its `alpha`; nil when
    62	    /// either has nothing ready (`wait` false) or both are drained (`wait` true).
    63	    func nextPacket(wait: Bool) throws -> ExportEncodedPacket? {
    64	        while let packet = try picture.nextPacket(wait: false) { pictures.append(packet) }
    65	        while let packet = try alpha.nextPacket(wait: false) { alphas.append(packet) }
    66	        if wait {
    67	            if pictures.isEmpty, !pictureDrained {
    68	                if let packet = try picture.nextPacket(wait: true) {
    69	                    pictures.append(packet)
    70	                } else {
    71	                    pictureDrained = true
    72	                }
    73	            }
    74	            if alphas.isEmpty, !alphaDrained {
    75	                if let packet = try alpha.nextPacket(wait: true) {
    76	                    alphas.append(packet)
    77	                } else {
    78	                    alphaDrained = true
    79	                }
    80	            }
    81	        }
    82	        return try Self.pair(&pictures, &alphas, drained: pictureDrained || alphaDrained)
    83	    }
    84	
    85	    func containerBytes(_ data: Data) throws -> Data {
    86	        try picture.containerBytes(data)
    87	    }
    88	
    89	    /// The oldest picture packet with the oldest alpha packet, both taken from their queues;
    90	    /// nil when either queue is empty and the streams are not `drained`, or both are empty. A
    91	    /// pts or key disagreement, or one stream ending before the other, throws.
    92	    static func pair(
    93	        _ pictures: inout [ExportEncodedPacket], _ alphas: inout [ExportEncodedPacket],
    94	        drained: Bool
    95	    ) throws -> ExportEncodedPacket? {
    96	        guard let p = pictures.first, let a = alphas.first else {
    97	            guard drained, let left = pictures.first ?? alphas.first else { return nil }
    98	            let which = pictures.isEmpty ? "alpha stream" : "picture"
    99	            throw Exporter.ExportError.failed(
   100	                "libvpx's \(which) answered frame \(left.pts) after the other stream ended.")
   101	        }
   102	        guard a.pts == p.pts else {
   103	            throw Exporter.ExportError.failed(
   104	                "libvpx's alpha stream answered frame \(a.pts) where the picture's answered "
   105	                    + "\(p.pts).")
   106	        }
   107	        guard a.isKey == p.isKey else {
   108	            throw Exporter.ExportError.failed(
   109	                "libvpx's alpha frame \(p.pts) and picture frame \(p.pts) disagree on being a "
   110	                    + "keyframe.")
   111	        }
   112	        pictures.removeFirst()
   113	        alphas.removeFirst()
   114	        return ExportEncodedPacket(
   115	            data: p.data, pts: p.pts, isLast: p.isLast, isKey: p.isKey, alpha: a.data)
   116	    }
   117	}
